import clsx from 'clsx';
import React, { forwardRef } from 'react';

import { codeCSS } from './Code.sty.js';
import type { DataTestId } from '../core/types/data-props.js';
import type { StylingProps } from '../core/types/styling-props.js';
import type { WithChildren } from '../core/types/with-children.js';

export interface CodeProps extends WithChildren, StylingProps, DataTestId {}

/**
 * Use the `Code` component to display snippets of code inline. If you want to
 * display a block of code, use the
 * {@link https://developer.dynatrace.com/reference/design-system/preview/content/CodeSnippet/ | `CodeSnippet`}
 * component instead.
 */
export const Code = /* @__PURE__ */ forwardRef<HTMLElement, CodeProps>(
  (props, ref) => {
    const {
      children,
      'data-testid': dataTestId,
      className: consumerClassName,
      style: consumerStyle,
      ...remainingProps
    } = props;
    return (
      <code
        ref={ref}
        data-testid={dataTestId}
        className={clsx(codeCSS, consumerClassName)}
        style={consumerStyle}
        {...remainingProps}
      >
        {children}
      </code>
    );
  },
);

(Code as typeof Code & { displayName: string }).displayName = 'Code';
